"""Intent tests for risk.annualize (RISK-03, TC-06): volatility annualized over 252 trading days."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pytest

from risk.annualize import annualize
from risk.types import Returns, VolSeries

FIXTURE = Path(__file__).resolve().parents[2] / "fixtures" / "risk" / "TC-06"


def _load(name: str) -> Any:
    return json.loads((FIXTURE / name).read_text())


def _vol_series(raw: dict[str, Any]) -> VolSeries:
    r = raw["returns"]
    returns = Returns(
        base_date=r["base_date"],
        dates=tuple(r["dates"]),
        tickers=tuple(r["tickers"]),
        values={t: tuple(v) for t, v in r["values"].items()},
    )
    return VolSeries(
        returns=returns,
        window=raw["window"],
        annualized=raw["annualized"],
        values={t: tuple(v) for t, v in raw["values"].items()},
    )


def _daily_vol() -> VolSeries:
    return _vol_series(_load("input.json")["vol"])


@pytest.mark.intent
def test_tc06_each_value_scaled_by_sqrt_252_and_gaps_kept() -> None:
    expected = _load("expected.json")
    tol = expected["tol"]
    result = annualize(_daily_vol())
    assert set(result.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = result.values[ticker]
        assert len(got) == len(want)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g is not None
                assert g == pytest.approx(w, abs=tol)


@pytest.mark.intent
def test_tc06_result_is_marked_annualized_and_keeps_returns_and_window() -> None:
    expected = _load("expected.json")
    vol = _daily_vol()
    result = annualize(vol)
    assert result.annualized is expected["annualized"]
    assert result.returns == vol.returns
    assert result.window == vol.window


@pytest.mark.intent
def test_tc06_default_matches_explicit_252_trading_days() -> None:
    expected = _load("expected.json")
    tol = expected["tol"]
    result = annualize(_daily_vol(), periods_per_year=252)
    for ticker, want in expected["values"].items():
        for g, w in zip(result.values[ticker], want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, abs=tol)


@pytest.mark.intent
def test_annualizing_an_annualized_series_is_a_value_error() -> None:
    once = annualize(_daily_vol())
    with pytest.raises(ValueError, match="annualized"):
        annualize(once)


@pytest.mark.intent
def test_annualizing_a_series_flagged_annualized_is_a_value_error() -> None:
    raw = dict(_load("input.json")["vol"])
    raw["annualized"] = True
    with pytest.raises(ValueError, match="annualized"):
        annualize(_vol_series(raw))

